package com.fava.marketpattern;
import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.webkit.WebView;import android.webkit.WebSettings;import android.webkit.JavascriptInterface;
import org.json.JSONObject;import java.net.URL;import java.net.HttpURLConnection;import java.net.URLEncoder;import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.InputStream;import java.nio.charset.StandardCharsets;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public class MainActivity extends Activity{
 WebView web;ExecutorService pool=Executors.newSingleThreadExecutor();Handler main=new Handler(Looper.getMainLooper());
 public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);web.addJavascriptInterface(new Bridge(),"MarketApi");setContentView(web);web.loadUrl("file:///android_asset/index.html");}
 class Bridge{@JavascriptInterface public void getCandles(String symbol,String key,String cb){pool.execute(()->{String out;HttpURLConnection c=null;try{String u="https://api.twelvedata.com/time_series?symbol="+URLEncoder.encode(symbol,"UTF-8")+"&interval=1min&outputsize=500&order=ASC&timezone=UTC&apikey="+URLEncoder.encode(key,"UTF-8");c=(HttpURLConnection)new URL(u).openConnection();c.setRequestMethod("GET");c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/json");int code=c.getResponseCode();InputStream is=code>=200&&code<300?c.getInputStream():c.getErrorStream();BufferedReader r=new BufferedReader(new InputStreamReader(is,StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();String line;while((line=r.readLine())!=null)b.append(line);r.close();out=b.toString();}catch(Exception e){JSONObject j=new JSONObject();try{j.put("status","error");j.put("message",e.getClass().getSimpleName()+": "+e.getMessage());}catch(Exception ignored){}out=j.toString();}finally{if(c!=null)c.disconnect();}final String q=JSONObject.quote(out);main.post(()->{if(web!=null)web.evaluateJavascript(cb+"("+q+")",null);});});}}
 public void onDestroy(){if(web!=null){web.removeJavascriptInterface("MarketApi");web.destroy();web=null;}pool.shutdownNow();super.onDestroy();}
}
